#define SEP_EFUSE_MAP__BL2_VERSION__VERSION_bm 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff
#define SEP_EFUSE_MAP__BL2_VERSION__VERSION_bp 0
